const event = $input.first().json;
const logs = String(event.sanitizedLogs || '').toLowerCase();
const incidentId = `inc_${Date.now().toString(36)}_${Math.random().toString(36).substring(2, 6)}`;

let severity = 'SEV-2';
let rootCause = 'Unspecified runtime exception detected in service stream.';
let actionType = 'inspect_logs';
let requiresApproval = false;
let actionParameters = { service: event.service };

if (logs.includes('exit code 137') || logs.includes('out of memory') || logs.includes('oomkilled')) {
  severity = 'SEV-1';
  rootCause = 'Process terminated with Exit Code 137 (OOM Killer). Memory limit exceeded.';
  actionType = 'docker_restart_container';
  requiresApproval = true;
  actionParameters = { service: event.service, adjustMemory: true };
} else if (logs.includes('exit code 139') || logs.includes('segmentation fault')) {
  severity = 'SEV-1';
  rootCause = 'Segmentation fault (Exit Code 139). Native binary memory corruption.';
  actionType = 'notify_team';
  requiresApproval = false;
} else if (logs.includes('401') || logs.includes('unauthorized') || logs.includes('bad credentials')) {
  severity = 'SEV-2';
  rootCause = 'Authentication failure: Service credentials expired or invalid token scope.';
  actionType = 'verify_credentials';
  requiresApproval = false;
} else if (logs.includes('econnrefused') || logs.includes('502 bad gateway') || logs.includes('no route to host')) {
  severity = 'SEV-2';
  rootCause = 'Network unreachable: Downstream port closed or container process not bound.';
  actionType = 'docker_restart_container';
  requiresApproval = true;
  actionParameters = { service: event.service };
} else {
  severity = 'SEV-3';
  rootCause = 'Telemetry warning or unclassified application error trace.';
  actionType = 'collect_diagnostics';
  requiresApproval = false;
}

return [{
  json: {
    incidentId,
    timestamp: new Date().toISOString(),
    service: event.service,
    environment: event.environment,
    source: event.source,
    severity,
    summary: `[${severity}] Incident on ${event.service} (${event.source})`,
    rootCause,
    recommendedAction: {
      type: actionType,
      parameters: actionParameters,
      requiresApproval
    },
    originalEvent: event
  }
}];
